package de.ga36.home;
import android.app.*;import android.content.*;import android.view.*;import android.widget.*;import java.util.Locale;
final class StickProbe extends TextView {
 long lastLog;
 StickProbe(Context c){super(c);setTextSize(18);setPadding(20,20,20,20);setMinHeight(170);setFocusable(true);setFocusableInTouchMode(true);setText(I18n.t("Linker Stick    X +0,00   Y +0,00\nRechter Stick  Z +0,00   RZ +0,00\nNoch keine Stickbewegung erkannt.\nB: Zurück"));}
 public boolean onGenericMotionEvent(MotionEvent e){if((e.getSource()&InputDevice.SOURCE_JOYSTICK)!=InputDevice.SOURCE_JOYSTICK||e.getAction()!=MotionEvent.ACTION_MOVE)return super.onGenericMotionEvent(e);float x=e.getAxisValue(MotionEvent.AXIS_X),y=e.getAxisValue(MotionEvent.AXIS_Y),z=e.getAxisValue(MotionEvent.AXIS_Z),rz=e.getAxisValue(MotionEvent.AXIS_RZ),rx=e.getAxisValue(MotionEvent.AXIS_RX),ry=e.getAxisValue(MotionEvent.AXIS_RY);setText(String.format(Locale.getDefault(),I18n.t("Linker Stick    X %+.2f   Y %+.2f\nRechter Stick  Z %+.2f   RZ %+.2f\nB: Zurück"),x,y,z,rz));if(e.getEventTime()-lastLog>=200){lastLog=e.getEventTime();android.util.Log.i("GA36Keys","STICK_PROBE device="+e.getDeviceId()+" source="+e.getSource()+" X="+x+" Y="+y+" Z="+z+" RZ="+rz+" RX="+rx+" RY="+ry);}return true;}
 static void show(Context c){final StickProbe view=new StickProbe(c);AlertDialog d=new AlertDialog(c){public boolean dispatchGenericMotionEvent(MotionEvent e){if((e.getSource()&InputDevice.SOURCE_JOYSTICK)==InputDevice.SOURCE_JOYSTICK)return view.onGenericMotionEvent(e);return super.dispatchGenericMotionEvent(e);}public boolean dispatchKeyEvent(KeyEvent e){if(e.getAction()==KeyEvent.ACTION_DOWN)android.util.Log.i("GA36Keys","PROBE_KEY scan="+e.getScanCode()+" key="+e.getKeyCode()+" source="+e.getSource());return super.dispatchKeyEvent(e);}};d.setTitle(I18n.t("Sticks prüfen"));d.setView(view);d.setButton(DialogInterface.BUTTON_NEGATIVE,I18n.t("Zurück"),new DialogInterface.OnClickListener(){public void onClick(DialogInterface x,int which){x.dismiss();}});GamepadDialog.attach(d);d.show();view.requestFocus();}
}
